## 4. Provider Router 구현

`src/router/provider-router.ts`

```ts
import {
  MessageProvider,
  ProviderType,
  SendMessageInput,
  SendMessageResult,
} from '../providers/provider';

export class ProviderRouter {
  private readonly providersByType: Map<ProviderType, MessageProvider[]>;

  constructor(providers: MessageProvider[]) {
    this.providersByType = new Map();

    for (const provider of providers) {
      const existing = this.providersByType.get(provider.type) ?? [];
      existing.push(provider);
      this.providersByType.set(provider.type, existing);
    }
  }

  async send(
    type: ProviderType,
    input: SendMessageInput,
  ): Promise<SendMessageResult> {
    const providers = this.providersByType.get(type);

    if (!providers || providers.length === 0) {
      throw new Error(`No provider registered for type: ${type}`);
    }

    let lastError: unknown;

    for (const provider of providers) {
      try {
        if (provider.isAvailable) {
          const available = await provider.isAvailable();
          if (!available) {
            continue;
          }
        }

        const result = await provider.send(input);

        if (result.success) {
          return result;
        }

        lastError = new Error(result.error ?? 'Unknown provider error');
      } catch (error) {
        lastError = error;
      }
    }

    throw new Error(
      `All providers failed for type=${type}, lastError=${String(lastError)}`,
    );
  }
}
```

포인트:

- 같은 타입에 대해 여러 provider를 등록할 수 있습니다.
- 첫 번째 provider 실패 시 다음 provider로 failover 가능합니다.
- 실무에서는 여기에 로깅, 메트릭, circuit breaker 등을 추가할 수 있습니다.

