### `providers/openaiProvider.ts`

```ts
import { AIProvider, AIRequest, AIResponse } from "../types";
import { AIProviderError } from "../errors";

interface OpenAIChatClient {
  responses: {
    create(params: Record<string, unknown>): Promise<any>;
  };
}

export class OpenAIProvider implements AIProvider {
  public readonly name = "openai";

  constructor(
    private readonly client: OpenAIChatClient,
    private readonly defaultModel: string
  ) {}

  async generate(request: AIRequest): Promise<AIResponse> {
    try {
      const response = await this.client.responses.create({
        model: request.model ?? this.defaultModel,
        input: request.messages.map((m) => ({
          role: m.role,
          content: m.content,
        })),
        temperature: request.temperature,
        max_output_tokens: request.maxTokens,
      });

      const content =
        response.output_text ??
        response.output?.[0]?.content?.[0]?.text ??
        "";

      if (!content) {
        throw new AIProviderError({
          provider: this.name,
          code: "UNKNOWN",
          message: "OpenAI returned empty content",
          retryable: false,
          cause: response,
        });
      }

      return {
        provider: this.name,
        model: request.model ?? this.defaultModel,
        content,
        usage: {
          inputTokens: response.usage?.input_tokens,
          outputTokens: response.usage?.output_tokens,
          totalTokens: response.usage?.total_tokens,
        },
        raw: response,
      };
    } catch (error: any) {
      throw normalizeOpenAIError(this.name, error);
    }
  }
}

function normalizeOpenAIError(provider: string, error: any): AIProviderError {
  const status = error?.status ?? error?.response?.status;

  if (status === 400) {
    return new AIProviderError({
      provider,
      code: "INVALID_REQUEST",
      message: error?.message ?? "Invalid request",
      retryable: false,
      status,
      cause: error,
    });
  }

  if (status === 401 || status === 403) {
    return new AIProviderError({
      provider,
      code: "AUTH",
      message: error?.message ?? "Authentication failed",
      retryable: false,
      status,
      cause: error,
    });
  }

  if (status === 429) {
    return new AIProviderError({
      provider,
      code: "RATE_LIMIT",
      message: error?.message ?? "Rate limited",
      retryable: true,
      status,
      cause: error,
    });
  }

  if (status && status >= 500) {
    return new AIProviderError({
      provider,
      code: "PROVIDER_UNAVAILABLE",
      message: error?.message ?? "Provider unavailable",
      retryable: true,
      status,
      cause: error,
    });
  }

  return new AIProviderError({
    provider,
    code: "NETWORK",
    message: error?.message ?? "Network or unknown error",
    retryable: true,
    status,
    cause: error,
  });
}
```

