  const trimmed = response.content.trim();
  if (!trimmed) {
    return { score: 0, reason: "empty content" };
  }

  // 필요시 JSON schema validation 등으로 확장 가능
  return { score: 1 };
}

function scoreCompleteness(
  response: ProviderResponse,
  context: EvaluationContext
): { score: number; reason?: string } {
  const content = response.content.trim();
  if (!content) {
    return { score: 0, reason: "no content" };
  }

  const requiredKeywords = context.requiredKeywords ?? [];
  if (requiredKeywords.length === 0) {
    // 키워드 기준이 없으면 길이 기반의 간단한 휴리스틱
    const lengthScore = clamp01(content.length / 300);
    return {
      score: lengthScore,
      reason: `length-based completeness=${lengthScore.toFixed(2)}`,
    };
  }

  const matched = countMatchedKeywords(content, requiredKeywords);
  const score = matched / requiredKeywords.length;

  return {
    score: clamp01(score),
    reason: `matched ${matched}/${requiredKeywords.length} required keywords`,
  };
}

function scoreSafety(
  response: ProviderResponse,
  context: EvaluationContext
): { score: number; reason?: string } {
  const bannedKeywords = context.bannedKeywords ?? [];
  if (bannedKeywords.length === 0) {
    return { score: 1 };
  }

  const hasBanned = containsAny(response.content, bannedKeywords);
  if (hasBanned) {
    return { score: 0, reason: "contains banned keywords" };
  }

  return { score: 1 };
}

function scoreLatency(
  response: ProviderResponse,
  allResponses: ProviderResponse[]
): { score: number; reason?: string } {
  const latencies = allResponses.map((r) => r.latencyMs);
  const min = Math.min(...latencies);
  const max = Math.max(...latencies);

  const score = normalizeInverse(response.latencyMs, min, max);
  return {
    score,
    reason: `latency=${response.latencyMs}ms, range=[${min}, ${max}]`,
  };
}

function scoreCost(
  response: ProviderResponse,
  allResponses: ProviderResponse[],
  context: EvaluationContext
): { score: number; reason?: string } {
  const costs = allResponses.map((r) => r.costUsd);
  const min = Math.min(...costs);
  const max = Math.max(...costs);

  let score = normalizeInverse(response.costUsd, min, max);

  if (context.maxBudgetUsd != null && response.costUsd > context.maxBudgetUsd) {
    score *= 0.5; // 예산 초과 패널티
    return {
      score,
      reason: `cost=$${response.costUsd.toFixed(4)} exceeds budget=$${context.maxBudgetUsd.toFixed(4)}`,
    };
  }

  return {
    score,
    reason: `cost=$${response.costUsd.toFixed(4)}, range=[$${min.toFixed(4)}, $${max.toFixed(4)}]`,
  };
}

export function evaluateResponses(
  responses: ProviderResponse[],
  context: EvaluationContext,
  weights: ScoreWeights = DEFAULT_WEIGHTS
): ScoreboardResult {
  if (responses.length === 0) {
    return {
      winner: null,
      ranked: [],
      weights,
    };
  }

  const ranked: WeightedScore[] = responses.map((response) => {
    const reasons: string[] = [];

    const validity = scoreValidity(response);
    if (validity.reason) reasons.push(`validity: ${validity.reason}`);

    const completeness = scoreCompleteness(response, context);
    if (completeness.reason) reasons.push(`completeness: ${completeness.reason}`);

    const latency = scoreLatency(response, responses);
    if (latency.reason) reasons.push(`latency: ${latency.reason}`);

    const cost = scoreCost(response, responses, context);
    if (cost.reason) reasons.push(`cost: ${cost.reason}`);

    const safety = scoreSafety(response, context);
    if (safety.reason) reasons.push(`safety: ${safety.reason}`);

    const breakdown: ScoreBreakdown = {
      validity: clamp01(validity.score),
      completeness: clamp01(completeness.score),
      latency: clamp01(latency.score),
      cost: clamp01(cost.score),
      safety: clamp01(safety.score),
    };

    const total =
      breakdown.validity * weights.validity +
      breakdown.completeness * weights.completeness +
      breakdown.latency * weights.latency +
      breakdown.cost * weights.cost +
      breakdown.safety * weights.safety;

    return {
      provider: response.provider,
      total: Number(total.toFixed(6)),
      breakdown,
      raw: response,
      reasons,
    };
  });

  ranked.sort((a, b) => {
    // 1. 총점 우선
    if (b.total !== a.total) return b.total - a.total;

    // 2. validity 높은 쪽
    if (b.breakdown.validity !== a.breakdown.validity) {
      return b.breakdown.validity - a.breakdown.validity;
    }

    // 3. completeness 높은 쪽
    if (b.breakdown.completeness !== a.breakdown.completeness) {
      return b.breakdown.completeness - a.breakdown.completeness;
    }

    // 4. latency 낮은 쪽
    if (a.raw.latencyMs !== b.raw.latencyMs) {
      return a.raw.latencyMs - b.raw.latencyMs;
    }

    // 5. cost 낮은 쪽
    if (a.raw.costUsd !== b.raw.costUsd) {
      return a.raw.costUsd - b.raw.costUsd;
    }

    return 0;
  });

  return {
    winner: ranked[0] ?? null,
    ranked,
    weights,
  };
}
