      reason: `cost=$${response.costUsd.toFixed(4)} exceeds budget=$${context.maxBudgetUsd.toFixed(4)}`,
    };
  }

  return {
    score,
    reason: `cost=$${response.costUsd.toFixed(4)}, range=[$${min.toFixed(4)}, $${max.toFixed(4)}]`,
  };
}

export function evaluateResponses(
  responses: ProviderResponse[],
  context: EvaluationContext,
  weights: ScoreWeights = DEFAULT_WEIGHTS
): ScoreboardResult {
  if (responses.length === 0) {
    return {
      winner: null,
      ranked: [],
      weights,
    };
  }

  const ranked: WeightedScore[] = responses.map((response) => {
    const reasons: string[] = [];

    const validity = scoreValidity(response);
    if (validity.reason) reasons.push(`validity: ${validity.reason}`);

    const completeness = scoreCompleteness(response, context);
    if (completeness.reason) reasons.push(`completeness: ${completeness.reason}`);

    const latency = scoreLatency(response, responses);
    if (latency.reason) reasons.push(`latency: ${latency.reason}`);

    const cost = scoreCost(response, responses, context);
    if (cost.reason) reasons.push(`cost: ${cost.reason}`);

    const safety = scoreSafety(response, context);
    if (safety.reason) reasons.push(`safety: ${safety.reason}`);

    const breakdown: ScoreBreakdown = {
      validity: clamp01(validity.score),
      completeness: clamp01(completeness.score),
      latency: clamp01(latency.score),
      cost: clamp01(cost.score),
      safety: clamp01(safety.score),
    };

    const total =
      breakdown.validity * weights.validity +
      breakdown.completeness * weights.completeness +
      breakdown.latency * weights.latency +
      breakdown.cost * weights.cost +
      breakdown.safety * weights.safety;

    return {
      provider: response.provider,
      total: Number(total.toFixed(6)),
      breakdown,
      raw: response,
      reasons,
    };
  });

  ranked.sort((a, b) => {
    // 1. 총점 우선
    if (b.total !== a.total) return b.total - a.total;

    // 2. validity 높은 쪽
    if (b.breakdown.validity !== a.breakdown.validity) {
      return b.breakdown.validity - a.breakdown.validity;
    }

    // 3. completeness 높은 쪽
    if (b.breakdown.completeness !== a.breakdown.completeness) {
      return b.breakdown.completeness - a.breakdown.completeness;
    }

    // 4. latency 낮은 쪽
    if (a.raw.latencyMs !== b.raw.latencyMs) {
      return a.raw.latencyMs - b.raw.latencyMs;
    }

    // 5. cost 낮은 쪽
    if (a.raw.costUsd !== b.raw.costUsd) {
      return a.raw.costUsd - b.raw.costUsd;
    }

    return 0;
  });

  return {
    winner: ranked[0] ?? null,
    ranked,
    weights,
  };
}
