```ts
import { ExecutionError } from "./errors.js";
import { Logger } from "./logger.js";
import {
  ExecutionResult,
  Plan,
  PlanStep,
  StepExecutionResult,
  TaskInput
} from "./types.js";

export interface Executor {
  execute(plan: Plan, input: TaskInput): Promise<ExecutionResult>;
}

export class SimpleExecutor implements Executor {
  constructor(private readonly logger: Logger) {}

  async execute(plan: Plan, input: TaskInput): Promise<ExecutionResult> {
    const startedAt = new Date().toISOString();
    const stepResults: StepExecutionResult[] = [];

    this.logger.info("Execution started", {
      requestId: input.requestId,
      planId: plan.planId
    });

    let workingValue: unknown = input.userGoal;

    for (const step of plan.steps) {
      const result = await this.executeStep(step, workingValue);
      stepResults.push(result);

      if (!result.success) {
        const finishedAt = new Date().toISOString();

        this.logger.warn("Execution failed at step", {
          requestId: input.requestId,
          planId: plan.planId,
          stepId: step.id,
          error: result.error
        });

        return {
          planId: plan.planId,
          success: false,
          stepResults,
          startedAt,
          finishedAt
        };
      }

      workingValue = result.output;
    }

    const finishedAt = new Date().toISOString();

    this.logger.info("Execution completed", {
      requestId: input.requestId,
      planId: plan.planId
    });

    return {
      planId: plan.planId,
      success: true,
      stepResults,
      finalOutput: workingValue,
      startedAt,
      finishedAt
    };
  }

  private async executeStep(
    step: PlanStep,
    input: unknown
  ): Promise<StepExecutionResult> {
    const startedAt = new Date().toISOString();

    try {
      let output: unknown;

      switch (step.type) {
        case "validate": {
          if (typeof input !== "string" || input.trim().length < 3) {
            throw new ExecutionError("Input must be a string with length >= 3");
          }
          output = input;
          break;
        }

        case "transform": {
          if (typeof input !== "string") {
            throw new ExecutionError("Transform step requires string input");
          }
          output = input.trim().toLowerCase().replace(/\s+/g, " ");
          break;
        }

        case "compute": {
          if (typeof input !== "string") {
            throw new ExecutionError("Compute step requires string input");
          }
          output = {
            normalizedText: input,
            length: input.length,
            wordCount: input.split(" ").filter(Boolean).length
          };
          break;
        }

        default: {
          const exhaustiveCheck: never = step.type;
          throw new ExecutionError(`Unsupported step type: ${exhaustiveCheck}`);
        }
      }

      return {
        stepId: step.id,
        success: true,
        output,
        startedAt,
        finishedAt: new Date().toISOString()
      };
    } catch (error) {
      return {
        stepId: step.id,
        success: false,
        error: error instanceof Error ? error.message : "Unknown execution error",
        startedAt,
        finishedAt: new Date().toISOString()
      };
    }
  }
}
