# 7. Planner: `src/planner.ts`

입력을 바탕으로 간단한 계획을 생성합니다.

```ts
import { randomUUID } from "node:crypto";
import { PlannerError } from "./errors.js";
import { Logger } from "./logger.js";
import { Plan, PlanStep, TaskInput } from "./types.js";

export interface Planner {
  createPlan(input: TaskInput): Promise<Plan>;
}

export class SimplePlanner implements Planner {
  constructor(private readonly logger: Logger) {}

  async createPlan(input: TaskInput): Promise<Plan> {
    this.logger.info("Creating plan", {
      requestId: input.requestId,
      userGoal: input.userGoal
    });

    if (!input.userGoal || input.userGoal.trim().length === 0) {
      throw new PlannerError("userGoal must not be empty");
    }

    const steps: PlanStep[] = [
      {
        id: randomUUID(),
        type: "validate",
        description: "Validate input goal"
      },
      {
        id: randomUUID(),
        type: "transform",
        description: "Normalize and transform goal text"
      },
      {
        id: randomUUID(),
        type: "compute",
        description: "Compute summary metrics"
      }
    ];

    return {
      planId: randomUUID(),
      steps,
      createdAt: new Date().toISOString()
    };
  }
}
```

