## 10) failover까지 넣은 간단한 확장 예시

같은 채널에 provider가 여러 개 있고, 하나 실패하면 다음 provider로 넘기고 싶다면 router를 이렇게 바꿀 수 있습니다.

### `src/router/provider-router.ts`

```ts
import { Provider } from '../providers/provider';
import { SendMessageInput, SendMessageResult } from '../types';

export class ProviderRouter {
  private readonly providers: Provider[];

  constructor(providers: Provider[]) {
    if (providers.length === 0) {
      throw new Error('At least one provider must be registered');
    }

    this.providers = [...providers].sort((a, b) => b.priority - a.priority);
  }

  getCandidates(input: SendMessageInput): Provider[] {
    return this.providers.filter((p) => p.supports(input));
  }

  async send(input: SendMessageInput): Promise<SendMessageResult> {
    const candidates = this.getCandidates(input);

    if (candidates.length === 0) {
      throw new Error(`No provider found for channel=${input.channel}`);
    }

    let lastError: unknown;

    for (const provider of candidates) {
      try {
        return await provider.send(input);
      } catch (error) {
        lastError = error;
        console.warn(`[ProviderRouter] ${provider.name} failed, trying next provider...`);
      }
    }

    throw new Error(
      `All providers failed for channel=${input.channel}, lastError=${String(lastError)}`
    );
  }
}
```

이렇게 하면:

- 1순위 provider 시도
- 실패하면 다음 provider 시도
- 전부 실패하면 에러 반환

