export type AIErrorCode =
  | "TIMEOUT"
  | "RATE_LIMIT"
  | "AUTH"
  | "BAD_REQUEST"
  | "NETWORK"
  | "PROVIDER"
  | "VALIDATION"
  | "UNKNOWN";

export class AIError extends Error {
  public readonly code: AIErrorCode;
  public readonly provider?: string;
  public readonly statusCode?: number;
  public readonly retryable: boolean;
  public override readonly cause?: unknown;

  constructor(params: {
    message: string;
    code: AIErrorCode;
    provider?: string;
    statusCode?: number;
    retryable?: boolean;
    cause?: unknown;
  }) {
    super(params.message);
    this.name = "AIError";
    this.code = params.code;
    this.provider = params.provider;
    this.statusCode = params.statusCode;
    this.retryable = params.retryable ?? false;
    this.cause = params.cause;
  }
}

export class AllProvidersFailedError extends Error {
  public readonly failures: AIError[];

  constructor(failures: AIError[]) {
    super("All AI providers failed");
    this.name = "AllProvidersFailedError";
    this.failures = failures;
  }
}

export function normalizeError(error: unknown, provider?: string): AIError {
  if (error instanceof AIError) {
    return error;
  }

  if (error instanceof Error) {
    if (error.name === "AbortError") {
      return new AIError({
        message: `Request timed out${provider ? ` for provider ${provider}` : ""}`,
        code: "TIMEOUT",
        provider,
        retryable: true,
        cause: error,
      });
    }

    return new AIError({
      message: error.message || "Unknown provider error",
      code: "UNKNOWN",
      provider,
      retryable: false,
      cause: error,
    });
  }

  return new AIError({
    message: "Unknown non-error thrown",
    code: "UNKNOWN",
    provider,
    retryable: false,
    cause: error,
  });
}
