## `src/ai/providers/openaiProvider.ts`

```ts
import { AIError } from "../errors";
import { AIProvider, AIRequest, AIResponse } from "../types";

export interface OpenAIProviderOptions {
  apiKey: string;
  baseUrl?: string;
  defaultModel: string;
}

export class OpenAIProvider implements AIProvider {
  public readonly name = "openai";
  private readonly apiKey: string;
  private readonly baseUrl: string;
  private readonly defaultModel: string;

  constructor(options: OpenAIProviderOptions) {
    this.apiKey = options.apiKey;
    this.baseUrl = options.baseUrl ?? "https://api.openai.com/v1";
    this.defaultModel = options.defaultModel;
  }

  async generate(request: AIRequest): Promise<AIResponse> {
    const response = await fetch(`${this.baseUrl}/chat/completions`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${this.apiKey}`,
      },
      signal: request.signal,
      body: JSON.stringify({
        model: request.model ?? this.defaultModel,
        messages: request.messages,
        temperature: request.temperature ?? 0.2,
        max_tokens: request.maxTokens,
      }),
    });

    if (!response.ok) {
      const text = await response.text().catch(() => "");
      throw this.mapHttpError(response.status, text);
    }

    const data = await response.json();

    const content = data?.choices?.[0]?.message?.content;
    if (!content || typeof content !== "string") {
      throw new AIError({
        message: "OpenAI response missing content",
        code: "PROVIDER",
        provider: this.name,
        retryable: false,
      });
    }

    return {
      provider: this.name,
      model: data.model ?? request.model ?? this.defaultModel,
      content,
      usage: {
        inputTokens: data.usage?.prompt_tokens,
        outputTokens: data.usage?.completion_tokens,
        totalTokens: data.usage?.total_tokens,
      },
      raw: data,
    };
  }

  private mapHttpError(status: number, body: string): AIError {
    if (status === 400) {
      return new AIError({
        message: `OpenAI bad request: ${body}`,
        code: "BAD_REQUEST",
        provider: this.name,
        statusCode: status,
        retryable: false,
      });
    }

    if (status === 401 || status === 403) {
      return new AIError({
        message: `OpenAI auth error: ${body}`,
        code: "AUTH",
        provider: this.name,
        statusCode: status,
        retryable: false,
      });
    }

    if (status === 429) {
      return new AIError({
        message: `OpenAI rate limit: ${body}`,
        code: "RATE_LIMIT",
        provider: this.name,
        statusCode: status,
        retryable: true,
      });
    }

    if (status >= 500) {
      return new AIError({
        message: `OpenAI server error: ${body}`,
        code: "PROVIDER",
        provider: this.name,
        statusCode: status,
        retryable: true,
      });
    }

    return new AIError({
      message: `OpenAI unexpected error: ${body}`,
      code: "PROVIDER",
      provider: this.name,
      statusCode: status,
      retryable: false,
    });
  }
}
