  if (error instanceof Error) {
    if (error.name === "AbortError") {
      return new AIError({
        message: `Request timed out${provider ? ` for provider ${provider}` : ""}`,
        code: "TIMEOUT",
        provider,
        retryable: true,
        cause: error,
      });
    }

    return new AIError({
      message: error.message || "Unknown provider error",
      code: "UNKNOWN",
      provider,
      retryable: false,
      cause: error,
    });
  }

  return new AIError({
    message: "Unknown non-error thrown",
    code: "UNKNOWN",
