## 4) 유틸리티: timeout, retry, sleep

### `src/ai/utils.ts`

```ts
import { AIError, normalizeError } from "./errors";
import { RetryPolicy } from "./types";

export function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export function computeBackoffDelay(
  attempt: number,
  baseDelayMs: number,
  maxDelayMs: number,
  backoffMultiplier: number
): number {
  const raw = baseDelayMs * Math.pow(backoffMultiplier, attempt - 1);
  const jitter = Math.random() * 0.2 * raw;
  return Math.min(maxDelayMs, Math.floor(raw + jitter));
}

export async function withTimeout<T>(
  fn: (signal: AbortSignal) => Promise<T>,
  timeoutMs: number
): Promise<T> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);

  try {
    return await fn(controller.signal);
  } catch (error) {
    throw normalizeError(error);
  } finally {
    clearTimeout(timeout);
  }
}

export function isRetryableError(
  error: AIError,
  retryPolicy: RetryPolicy
): boolean {
  if (error.retryable) return true;
  if (
    error.statusCode &&
    retryPolicy.retryableStatusCodes?.includes(error.statusCode)
  ) {
    return true;
  }
  return false;
}

export async function retry<T>(params: {
  operation: () => Promise<T>;
  retryPolicy: RetryPolicy;
  onRetry?: (info: {
    attempt: number;
    delayMs: number;
    error: AIError;
  }) => void;
}): Promise<T> {
  const { operation, retryPolicy, onRetry } = params;

  let lastError: AIError | undefined;

  for (let attempt = 1; attempt <= retryPolicy.maxAttempts; attempt++) {
    try {
      return await operation();
    } catch (error) {
      const normalized = normalizeError(error);
      lastError = normalized;

      const shouldRetry =
        attempt < retryPolicy.maxAttempts &&
        isRetryableError(normalized, retryPolicy);

      if (!shouldRetry) {
        throw normalized;
      }

      const delayMs = computeBackoffDelay(
        attempt,
        retryPolicy.baseDelayMs,
        retryPolicy.maxDelayMs,
        retryPolicy.backoffMultiplier
      );

      onRetry?.({ attempt, delayMs, error: normalized });
      await sleep(delayMs);
    }
  }

  throw lastError ?? new AIError({
    message: "Retry failed with unknown error",
    code: "UNKNOWN",
  });
}
```

