# 7) 유틸 함수

## 셔플

```ts
function shuffleCandidates(
  candidates: [CandidateResponse, CandidateResponse]
): {
  shuffled: [CandidateResponse, CandidateResponse];
  candidateOrder: [Provider, Provider];
  wasShuffled: boolean;
} {
  const flip = Math.random() < 0.5;
  const shuffled = flip
    ? [candidates[1], candidates[0]]
    : [candidates[0], candidates[1]];

  return {
    shuffled: shuffled as [CandidateResponse, CandidateResponse],
    candidateOrder: [shuffled[0].provider, shuffled[1].provider],
    wasShuffled: flip,
  };
}
