# JSON schema validation

운영에서는 judge 출력이 깨질 수 있으므로 `zod` 같은 검증기가 좋습니다.

```ts
import { z } from "zod";

export const JudgeLLMResultSchema = z.object({
  winner: z.union([z.literal("A"), z.literal("B"), z.literal("tie")]),
  confidence: z.number().min(0).max(1),
  summary: z.string().min(1),
  criteria: z.array(
    z.object({
      name: z.union([
        z.literal("instruction_following"),
        z.literal("correctness"),
        z.literal("completeness"),
        z.literal("clarity"),
        z.literal("safety"),
        z.literal("format"),
      ]),
      scoreA: z.number().int().min(1).max(10),
      scoreB: z.number().int().min(1).max(10),
      rationale: z.string().min(1),
