# 4) Precheck

LLM 호출 전에 명백한 실패를 잡습니다.

```ts
export interface PrecheckResult {
  forcedWinner?: JudgeWinner;
  reason?: string;
  penalties: Record<Provider, number>;
}

export function runPrecheck(input: JudgeInput): PrecheckResult {
  const penalties: Record<Provider, number> = {
    openai: 0,
    claude: 0,
  };

  for (const candidate of input.candidates) {
    const text = candidate.content.trim();

    if (!text) penalties[candidate.provider] += 100;
    if (text.length < 20) penalties[candidate.provider] += 10;

    if (input.expectedFormat === "json") {
      try {
        JSON.parse(text);
      } catch {
        penalties[candidate.provider] += 20;
      }
    }

    const refusalPatterns = [
      /i can't help with that/i,
      /i cannot help with that/i,
      /sorry,? i can't/i,
      /죄송하지만/i,
      /도와드릴 수 없습니다/i,
    ];

    if (refusalPatterns.some((re) => re.test(text))) {
      penalties[candidate.provider] += 15;
    }
  }

  const [c1, c2] = input.candidates;
  const diff = penalties[c1.provider] - penalties[c2.provider];

  if (Math.abs(diff) >= 50) {
    return {
      forcedWinner: diff < 0 ? c1.provider : c2.provider,
      reason: "Precheck forced decision due to severe failure",
      penalties,
    };
  }

  return { penalties };
}
```

