예시 fetch 기반 구현:

```ts
export class OpenAIJudgeClient implements LLMJudgeClient {
  public readonly modelName: string;

  constructor(
    private readonly apiKey: string,
    model = "gpt-4.1"
  ) {
    this.modelName = model;
  }

  async evaluate(params: {
    systemPrompt: string;
    userPrompt: string;
    timeoutMs?: number;
  }): Promise<string> {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), params.timeoutMs ?? 10000);

    try {
      const res = await fetch("https://api.openai.com/v1/responses", {
        method: "POST",
        signal: controller.signal,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${this.apiKey}`,
        },
        body: JSON.stringify({
          model: this.modelName,
          temperature: 0,
          input: [
            { role: "system", content: params.systemPrompt },
            { role: "user", content: params.userPrompt },
          ],
        }),
      });

      if (!res.ok) {
        throw new Error(`Judge API failed: ${res.status} ${await res.text()}`);
      }

      const json = await res.json();

      // 환경별 응답 포맷 차이를 흡수
      const text =
        json.output_text ??
        json.output?.[0]?.content?.[0]?.text ??
        json.choices?.[0]?.message?.content;

      if (!text || typeof text !== "string") {
        throw new Error("Judge response text not found");
      }

      return text;
    } finally {
      clearTimeout(timeout);
    }
  }
}
```

