# Rule-based precheck 설계

LLM judge 전에 빠르게 걸러낼 수 있는 규칙입니다.

```ts
export interface PrecheckResult {
  forcedWinner?: JudgeWinner;
  reason?: string;
  penalties: Record<Provider, number>;
}

function runPrecheck(input: JudgeInput): PrecheckResult {
  const penalties: Record<Provider, number> = {
    openai: 0,
    claude: 0,
  };

  for (const candidate of input.candidates) {
    const text = candidate.content.trim();

    if (!text) {
      penalties[candidate.provider] += 100;
    }

    if (text.length < 20) {
      penalties[candidate.provider] += 10;
    }

    if (input.expectedFormat === "json") {
      try {
        JSON.parse(text);
      } catch {
        penalties[candidate.provider] += 20;
      }
    }

    // 너무 노골적인 무응답/회피
    const refusalPatterns = [
      /i can't help with that/i,
      /i cannot help with that/i,
      /죄송하지만/i,
      /도와드릴 수 없습니다/i,
    ];

    if (refusalPatterns.some((re) => re.test(text))) {
      penalties[candidate.provider] += 15;
    }
  }

  const [a, b] = input.candidates;
  const diff = penalties[a.provider] - penalties[b.provider];

  if (Math.abs(diff) >= 50) {
    return {
      forcedWinner: diff < 0 ? a.provider : b.provider,
      reason: "Precheck forced decision due to severe quality/format failure",
      penalties,
    };
  }

  return { penalties };
}
```

