## 1) 핵심 구현

### `scoreboard.ts`

```ts
// scoreboard.ts

export type ProviderName = "openai" | "anthropic" | "google" | "custom";

export interface ProviderResponse<T = unknown> {
  provider: ProviderName;
  success: boolean;
  data?: T;
  error?: string;

  // 메타 정보
  latencyMs: number;
  costUsd?: number;
  confidence?: number; // 0 ~ 1
  rawText?: string;
}

export interface ScoreBreakdown {
  dimension: string;
  raw: number;       // 0 ~ 1
  weighted: number;  // raw * weight
  reason?: string;
}

export interface ScoredProvider<T = unknown> {
  response: ProviderResponse<T>;
  totalScore: number;
  breakdown: ScoreBreakdown[];
  disqualified?: boolean;
  disqualifyReason?: string;
}

export interface WinnerResult<T = unknown> {
  winner: ScoredProvider<T> | null;
  ranked: ScoredProvider<T>[];
  reason: string;
}

export interface ScoreContext<T = unknown> {
  prompt?: string;
  expectedSchema?: Record<string, unknown>;
  custom?: Record<string, unknown>;
  responses: ProviderResponse<T>[];
}

export interface ScoreDimension<T = unknown> {
  name: string;
  weight: number;
  score: (
    response: ProviderResponse<T>,
    context: ScoreContext<T>
  ) => {
    score: number; // 0 ~ 1 권장
    reason?: string;
    disqualify?: boolean;
    disqualifyReason?: string;
  };
}

export interface ScoreboardConfig<T = unknown> {
  dimensions: ScoreDimension<T>[];
  tieBreaker?: (a: ScoredProvider<T>, b: ScoredProvider<T>) => number;
  minimumScore?: number;
}

function clamp01(value: number): number {
  if (Number.isNaN(value)) return 0;
  return Math.max(0, Math.min(1, value));
}

export function evaluateProviders<T>(
  responses: ProviderResponse<T>[],
  config: ScoreboardConfig<T>,
  contextInput?: Omit<ScoreContext<T>, "responses">
): WinnerResult<T> {
  const context: ScoreContext<T> = {
    ...contextInput,
    responses,
  };

  const scored: ScoredProvider<T>[] = responses.map((response) => {
    const breakdown: ScoreBreakdown[] = [];
    let totalScore = 0;
    let disqualified = false;
    let disqualifyReason: string | undefined;

    for (const dimension of config.dimensions) {
      const result = dimension.score(response, context);

      if (result.disqualify) {
        disqualified = true;
        disqualifyReason =
          result.disqualifyReason ?? `Disqualified by ${dimension.name}`;
      }

      const raw = clamp01(result.score);
      const weighted = raw * dimension.weight;

      breakdown.push({
        dimension: dimension.name,
        raw,
        weighted,
        reason: result.reason,
      });

      totalScore += weighted;
    }

    if (disqualified) {
      totalScore = -1;
    }

    return {
      response,
      totalScore,
      breakdown,
      disqualified,
      disqualifyReason,
    };
  });

  scored.sort((a, b) => {
    if (b.totalScore !== a.totalScore) {
      return b.totalScore - a.totalScore;
    }

    if (config.tieBreaker) {
      return config.tieBreaker(a, b);
    }

    // 기본 tie-breaker
    // 1) success=true 우선
    // 2) latency 낮은 쪽 우선
    // 3) cost 낮은 쪽 우선
    if (a.response.success !== b.response.success) {
      return Number(b.response.success) - Number(a.response.success);
    }

    if (a.response.latencyMs !== b.response.latencyMs) {
      return a.response.latencyMs - b.response.latencyMs;
    }

    const aCost = a.response.costUsd ?? Number.POSITIVE_INFINITY;
    const bCost = b.response.costUsd ?? Number.POSITIVE_INFINITY;
    return aCost - bCost;
  });

  const top = scored[0] ?? null;

  if (!top) {
    return {
      winner: null,
      ranked: [],
      reason: "No provider responses available",
    };
  }

  if (top.disqualified) {
    return {
      winner: null,
      ranked: scored,
      reason: `Top candidate disqualified: ${top.disqualifyReason ?? "unknown reason"}`,
    };
  }

  if (
    config.minimumScore !== undefined &&
    top.totalScore < config.minimumScore
  ) {
    return {
      winner: null,
      ranked: scored,
      reason: `No provider met minimum score threshold (${config.minimumScore})`,
    };
  }

  return {
    winner: top,
    ranked: scored,
    reason: `Winner selected: ${top.response.provider}`,
  };
}
```

