## 2) scoring dimension 예시

### `dimensions.ts`

```ts
// dimensions.ts

import {
  ProviderResponse,
  ScoreContext,
  ScoreDimension,
} from "./scoreboard";

/**
 * 성공 여부
 */
export function successDimension<T>(weight = 0.35): ScoreDimension<T> {
  return {
    name: "success",
    weight,
    score: (response) => {
      if (!response.success) {
        return {
          score: 0,
          reason: response.error ?? "Provider failed",
        };
      }

      return {
        score: 1,
        reason: "Provider succeeded",
      };
    },
  };
}

/**
 * latency가 낮을수록 높은 점수
 */
export function latencyDimension<T>(
  maxAcceptableMs = 5000,
  weight = 0.2
): ScoreDimension<T> {
  return {
    name: "latency",
    weight,
    score: (response) => {
      if (!response.success) {
        return { score: 0, reason: "No latency credit for failed response" };
      }

      const normalized = 1 - Math.min(response.latencyMs / maxAcceptableMs, 1);

      return {
        score: normalized,
        reason: `Latency ${response.latencyMs}ms`,
      };
    },
  };
}

/**
 * cost가 낮을수록 높은 점수
 */
export function costDimension<T>(
  maxCostUsd = 0.05,
  weight = 0.1
): ScoreDimension<T> {
  return {
    name: "cost",
    weight,
    score: (response) => {
      if (!response.success) {
        return { score: 0, reason: "No cost credit for failed response" };
      }

      const cost = response.costUsd ?? maxCostUsd;
      const normalized = 1 - Math.min(cost / maxCostUsd, 1);

      return {
        score: normalized,
        reason: `Cost $${cost.toFixed(4)}`,
      };
    },
  };
}

/**
 * confidence 사용
 */
export function confidenceDimension<T>(weight = 0.15): ScoreDimension<T> {
  return {
    name: "confidence",
    weight,
    score: (response) => {
      if (!response.success) {
        return { score: 0, reason: "Failed response" };
      }

      return {
        score: response.confidence ?? 0.5,
        reason: `Confidence ${response.confidence ?? 0.5}`,
      };
    },
  };
}

/**
 * 텍스트 길이 기반 completeness 예시
 */
export function completenessDimension<T>(
  minLength = 50,
  idealLength = 300,
  weight = 0.2
): ScoreDimension<T> {
  return {
    name: "completeness",
    weight,
    score: (response) => {
      if (!response.success) {
        return { score: 0, reason: "Failed response" };
      }

      const text = response.rawText ?? "";
      const len = text.trim().length;

      if (len === 0) {
        return { score: 0, reason: "Empty response" };
      }

      if (len < minLength) {
        return {
          score: len / minLength,
          reason: `Too short (${len} chars)`,
        };
      }

      return {
        score: Math.min(len / idealLength, 1),
        reason: `Length ${len} chars`,
      };
    },
  };
}

/**
 * 필수 필드 존재 여부
 */
export function requiredFieldsDimension<T extends Record<string, unknown>>(
  requiredFields: string[],
  weight = 0.25
): ScoreDimension<T> {
  return {
    name: "required_fields",
    weight,
    score: (response: ProviderResponse<T>, _context: ScoreContext<T>) => {
      if (!response.success || !response.data) {
        return {
          score: 0,
          reason: "No structured data",
        };
      }

      const present = requiredFields.filter((field) => field in response.data!);
      const ratio = present.length / requiredFields.length;

      return {
        score: ratio,
        reason: `Present fields: ${present.length}/${requiredFields.length}`,
        disqualify: ratio === 0,
        disqualifyReason:
          ratio === 0 ? "Missing all required fields" : undefined,
      };
    },
  };
}
```

