      }

      return {
        score: 1,
        reason: "Provider succeeded",
      };
    },
  };
}

/**
 * latency가 낮을수록 높은 점수
 * maxAcceptableMs를 넘으면 0점
 */
export function latencyDimension<T>(maxAcceptableMs = 5000): ScoreDimension<T> {
  return {
    name: "latency",
    weight: 0.2,
    score: (response) => {
      if (!response.success) {
        return { score: 0, reason: "No latency credit for failed response" };
      }

      const latency = response.latencyMs;
      const normalized = 1 - Math.min(latency / maxAcceptableMs, 1);

      return {
        score: normalized,
        reason: `Latency ${latency}ms`,
      };
    },
  };
}

/**
 * cost가 낮을수록 높은 점수
 * maxCostUsd 이상이면 0점
 */
export function costDimension<T>(maxCostUsd = 0.05): ScoreDimension<T> {
  return {
    name: "cost",
    weight: 0.1,
    score: (response) => {
      if (!response.success) {
        return { score: 0, reason: "No cost credit for failed response" };
      }

      const cost = response.costUsd ?? maxCostUsd;
      const normalized = 1 - Math.min(cost / maxCostUsd, 1);

      return {
        score: normalized,
        reason: `Cost $${cost.toFixed(4)}`,
      };
    },
  };
}

/**
 * confidence 점수 사용
 */
export function confidenceDimension<T>(): ScoreDimension<T> {
  return {
    name: "confidence",
    weight: 0.15,
    score: (response) => {
      if (!response.success) {
        return { score: 0, reason: "Failed response" };
      }

      const confidence = response.confidence ?? 0.5;
      return {
        score: confidence,
        reason: `Confidence ${confidence}`,
      };
    },
  };
}

/**
 * 텍스트 completeness 예시:
 * rawText 길이가 너무 짧으면 낮은 점수
 */
export function completenessDimension<T>(minLength = 50, idealLength = 300): ScoreDimension<T> {
  return {
    name: "completeness",
    weight: 0.2,
    score: (response) => {
      if (!response.success) {
        return { score: 0, reason: "Failed response" };
      }

      const text = response.rawText ?? "";
      const len = text.trim().length;

      if (len === 0) {
        return { score: 0, reason: "Empty response" };
      }

      if (len < minLength) {
        return {
          score: len / minLength,
          reason: `Too short (${len} chars)`,
        };
      }

      const score = Math.min(len / idealLength, 1);
      return {
        score,
        reason: `Length ${len} chars`,
      };
    },
  };
}

/**
 * JSON schema-like validation 예시
 * 실제로는 zod/ajv 사용 권장
 */
export function requiredFieldsDimension<T extends Record<string, unknown>>(
  requiredFields: string[]
): ScoreDimension<T> {
  return {
    name: "required_fields",
    weight: 0.25,
    score: (response: ProviderResponse<T>, _context: ScoreContext<T>) => {
      if (!response.success || !response.data) {
        return {
          score: 0,
          reason: "No structured data",
        };
      }

      const present = requiredFields.filter((field) => field in response.data!);
      const ratio = present.length / requiredFields.length;

      return {
        score: ratio,
        reason: `Present fields: ${present.length}/${requiredFields.length}`,
        disqualify: ratio === 0,
        disqualifyReason: ratio === 0 ? "Missing all required fields" : undefined,
      };
    },
  };
}
