```ts
import {
  ExecutionResult,
  Plan,
  PlanStep,
  StepExecutionResult,
  WorkflowInput
} from "./types";
import { nowIso, sleep, toErrorMessage, withRetry } from "./utils";

export interface Executor {
  execute(plan: Plan, input: WorkflowInput): Promise<ExecutionResult>;
}

export class SimpleExecutor implements Executor {
  async execute(plan: Plan, input: WorkflowInput): Promise<ExecutionResult> {
    const stepResults: StepExecutionResult[] = [];

    for (const step of plan.steps) {
      const result = await this.executeStepWithSafety(step, input);
      stepResults.push(result);

      if (!result.success) {
        return {
          success: false,
          stepResults
        };
      }
    }

    return {
      success: true,
      stepResults
    };
  }

  private async executeStepWithSafety(
    step: PlanStep,
    input: WorkflowInput
  ): Promise<StepExecutionResult> {
    const started = Date.now();
    const startedAt = nowIso();

    try {
      const output = await withRetry(
        async () => this.executeStep(step, input),
        {
          retries: 2,
          delayMs: 200,
          shouldRetry: (error) => toErrorMessage(error).includes("transient")
        }
      );

      const finished = Date.now();

      return {
        stepId: step.id,
        action: step.action,
        success: true,
        output,
        startedAt,
        finishedAt: nowIso(),
        durationMs: finished - started
      };
    } catch (error) {
      const finished = Date.now();

      return {
        stepId: step.id,
        action: step.action,
        success: false,
        error: toErrorMessage(error),
        startedAt,
        finishedAt: nowIso(),
        durationMs: finished - started
      };
    }
  }

  private async executeStep(step: PlanStep, input: WorkflowInput): Promise<unknown> {
    switch (step.action) {
      case "VALIDATE_INPUT":
        return this.validateInput(input);

      case "FETCH_DATA":
        return this.fetchData(step.payload?.query);

      case "TRANSFORM_DATA":
        return this.transformData();

      case "GENERATE_SUMMARY":
        return this.generateSummary(input);

      default: {
        const exhaustiveCheck: never = step.action;
        throw new Error(`Unsupported action: ${exhaustiveCheck}`);
      }
    }
  }

  private async validateInput(input: WorkflowInput): Promise<{ valid: true }> {
    await sleep(100);

    if (!input.userGoal || input.userGoal.trim().length < 3) {
      throw new Error("Invalid input: userGoal must be at least 3 characters");
    }

    return { valid: true };
  }

  private async fetchData(query: unknown): Promise<{ items: string[] }> {
    await sleep(200);

    if (typeof query !== "string" || query.trim() === "") {
      throw new Error("Invalid query payload");
    }

    // transient 에러 시뮬레이션
    if (query.includes("retry") && Math.random() < 0.5) {
      throw new Error("transient network error");
    }

    return {
      items: [
        `data-for:${query}:1`,
        `data-for:${query}:2`,
        `data-for:${query}:3`
      ]
    };
  }

  private async transformData(): Promise<{ normalized: string[] }> {
    await sleep(150);

    return {
      normalized: ["normalized-item-1", "normalized-item-2", "normalized-item-3"]
    };
  }

  private async generateSummary(input: WorkflowInput): Promise<{ summary: string }> {
    await sleep(120);

    return {
      summary: `Summary generated for goal: "${input.userGoal}"`
    };
  }
}
