import { ExecutionResult, JudgeResult, Plan, WorkflowInput } from "./types";

export interface Judge {
  evaluate(input: WorkflowInput, plan: Plan, execution: ExecutionResult): Promise<JudgeResult>;
}

export class SimpleJudge implements Judge {
  async evaluate(
    _input: WorkflowInput,
    plan: Plan,
    execution: ExecutionResult
  ): Promise<JudgeResult> {
    const reasons: string[] = [];
    let score = 100;

    if (plan.steps.length === 0) {
      score -= 50;
      reasons.push("Plan contains no steps.");
    }

    if (!execution.success) {
      score -= 60;
      reasons.push("Execution did not complete successfully.");
    }

    const failedSteps = execution.stepResults.filter((r) => !r.success);
    if (failedSteps.length > 0) {
      reasons.push(
        `Failed steps: ${failedSteps.map((s) => `${s.stepId}(${s.action})`).join(", ")}`
      );
    }

    const hasSummary = execution.stepResults.some(
      (r) =>
        r.action === "GENERATE_SUMMARY" &&
        r.success &&
        typeof r.output === "object" &&
        r.output !== null &&
        "summary" in r.output
    );

    if (!hasSummary) {
      score -= 20;
      reasons.push("Summary output is missing.");
    }

    if (reasons.length === 0) {
      reasons.push("Execution result passed all checks.");
    }

    return {
      approved: score >= 70 && execution.success,
      score: Math.max(0, score),
      reasons
    };
  }
}
