```ts
import { Plan, WorkflowInput } from "./types";

export interface Planner {
  createPlan(input: WorkflowInput): Promise<Plan>;
}

export class SimplePlanner implements Planner {
  async createPlan(input: WorkflowInput): Promise<Plan> {
    const steps = [
      {
        id: "step-1",
        action: "VALIDATE_INPUT" as const,
        description: "Validate the incoming user goal"
      },
      {
        id: "step-2",
        action: "FETCH_DATA" as const,
        description: "Fetch data relevant to the user goal",
        payload: {
          query: input.userGoal
        }
      },
      {
        id: "step-3",
        action: "TRANSFORM_DATA" as const,
        description: "Transform fetched data into a normalized structure"
      },
      {
        id: "step-4",
        action: "GENERATE_SUMMARY" as const,
        description: "Generate a concise summary for the user"
      }
    ];

    return {
      steps,
      rationale: `Created a 4-step plan for request "${input.requestId}" based on user goal.`
    };
  }
}
